      .respond(new AIMessage("It's 72°F and sunny in SF!"));
const { finalResponse } = await runAgent(model, "Weather in SF?");
expect(finalResponse.content).toBe("It's 72°F and sunny in SF!");
expect(model.callCount).toBe(2);
