ConditionalEdgeRouter
Use ConditionalEdgeRouter for routing functions in conditional edges (no state updates, just
routing):
import { ConditionalEdgeRouter, END } from "@langchain/langgraph";
const State = new StateSchema({
  shouldContinue: z.boolean(),
  step: z.string(),
});
// Router returns node name(s) or END
const router: ConditionalEdgeRouter<{ InputSchema: typeof State; Nodes: "process" | "summarize"
}> = (state) => {
  if (!state.shouldContinue) {
    return END;
  }
  return state.step === "initial" ? "process" : "summarize";
};
// Use in graph
graph.addConditionalEdges("check", router);
